{
  "name": "Keithley 6514 静电计",
  "name_en": "Keithley 6514 Electrometer",
  "manufacturer": "Keithley Instruments",
  "description": "Keithley 6514 是一款高灵敏度静电计，可进行微弱电流、电荷、电压和电阻测量。它常用于低电平电学测试、漏电流表征、绝缘材料评估以及需要高输入阻抗和高分辨率的实验测量。",
  "description_en": "The Keithley 6514 is a high-sensitivity electrometer for measuring very small currents, charge, voltage, and resistance. It is commonly used for low-level electrical measurements, leakage current characterization, insulation testing, and experiments requiring high input impedance and high resolution.",
  "tag_hints": [
    "electrometer",
    "low current measurement",
    "charge measurement",
    "high impedance measurement",
    "leakage current testing",
    "voltage and resistance measurement",
    "SCPI instrument"
  ],
  "actions": [
    {
      "action_name": "auto-arm_source",
      "description": "获取/设置布防源",
      "description_en": "Get/set the arm source"
    },
    {
      "action_name": "auto-auto_config",
      "description": "按指定测量模式自动配置仪器，并将相关设置恢复为默认值。",
      "description_en": "Automatically configure the instrument for the specified measurement mode and reset related settings to their defaults."
    },
    {
      "action_name": "auto-auto_range",
      "description": "获取/设置自动量程",
      "description_en": "Get/set auto ranging"
    },
    {
      "action_name": "auto-fetch",
      "description": "获取当前模式下最近一次处理后的读数和时间戳，不发出触发。",
      "description_en": "Fetch the latest post-processed reading and timestamp in the current mode without issuing a trigger."
    },
    {
      "action_name": "auto-input_range",
      "description": "获取/设置输入量程上限",
      "description_en": "Get/set the input range upper limit"
    },
    {
      "action_name": "auto-mode",
      "description": "获取/设置测量模式",
      "description_en": "Get/set the measurement mode"
    },
    {
      "action_name": "auto-read_measurements",
      "description": "触发并读取当前模式下的测量值和时间戳。",
      "description_en": "Trigger and read a measurement and timestamp in the current mode."
    },
    {
      "action_name": "auto-trigger_mode",
      "description": "获取/设置触发模式",
      "description_en": "Get/set the trigger mode"
    },
    {
      "action_name": "auto-zero_check",
      "description": "获取/设置零点检查",
      "description_en": "Get/set zero check"
    },
    {
      "action_name": "auto-zero_correct",
      "description": "获取/设置零点校正",
      "description_en": "Get/set zero correction"
    },
    {
      "action_name": "auto-unit",
      "description": "获取/设置测量单位",
      "description_en": "Get/set the measurement unit"
    }
  ]
}

